package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.util.StringUtils;

/**
 * Assigns a newly built owner its numeric {@code membershipLevel}. Starting from 1, the level
 * gains a point when the owner has an email address and another when it had no namesakes at
 * creation ({@link Owner#getNamesakeCount()} is 0), capped at 3. Level 4 is reserved for tenure
 * and so is never assigned here. Runs after {@link CountNamesakes} so the namesake count is set.
 */
public class AssignMembershipLevel {

    /** The highest membership level assignable on creation; level 4 is reserved for tenure. */
    private static final int MAX_LEVEL_ON_CREATION = 3;

    public void service(@Val Owner owner) {
        int level = 1;
        if (StringUtils.hasText(owner.getEmail())) {
            level++;
        }
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
            level++;
        }
        owner.setMembershipLevel(Math.min(level, MAX_LEVEL_ON_CREATION));
    }
}
===== AssignMembershipNumber =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns a newly built owner its {@code membershipNumber}, formatted
 * {@code <customerCode>-M<YY>}, where YY is the last two digits of the registration
 * date year (e.g. {@code NSW-1A2B3C4D-M26}). Runs after both the customer code and the
 * registration date have been assigned, so both inputs are present.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        int yy = owner.getRegistrationDate().getYear() % 100;
        owner.setMembershipNumber(String.format("%s-M%02d", owner.getCustomerCode(), yy));
    }
}
===== Household =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Sha256;

/**
 * Household identity shared by the create-owner steps. A household is the set of owners with the same
 * last name (compared case-insensitively with collapsed whitespace) and the same normalized address
 * (see {@link AddressNormalizer}). Used by {@link AssignHousehold} to give the members that opt into
 * sharing a single shared {@code householdId}, which then forms part of each owner's identity key.
 */
final class Household {

    private Household() {
    }

    /** Case-insensitive form with leading/trailing and repeated inner whitespace collapsed to one space. */
    static String canonical(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /** Whether {@code owner} belongs to the household identified by the given last name and address. */
    static boolean matches(Owner owner, String lastName, String address) {
        return canonical(owner.getLastName()).equals(canonical(lastName))
                && AddressNormalizer.normalize(owner.getAddress()).equals(AddressNormalizer.normalize(address));
    }

    /** A stable identifier for the household at the given last name and address, of the form {@code H-<hex>}. */
    static String idFor(String lastName, String address) {
        String hex = Sha256.hex(canonical(lastName) + '|' + AddressNormalizer.normalize(address));
        return "H-" + hex.substring(0, 12);
    }
}

